<?php
$title='Prompts & Messages';
$types=Seed::types();
$t=isset($types[$_GET['t']??''])?$_GET['t']:'report_website';
if(is_post()){
  $a=$_POST['a']??'';$id=(int)($_POST['id']??0);
  $pt=isset($types[$_POST['type']??''])?$_POST['type']:$t;
  if($a==='save'){
    $d=['type'=>$pt,'name'=>mb_substr(trim($_POST['name']??'Untitled'),0,180)?:'Untitled','subject'=>mb_substr(trim($_POST['subject']??''),0,250),'content'=>trim($_POST['content']??'')];
    if($d['content']===''){flash('Content cannot be empty.','err');back();}
    if($id)DB::update('prompts',$d,'id=?',[$id]);else{$id=DB::insert('prompts',$d);}
    if(!empty($_POST['use'])||!DB::val('SELECT COUNT(*) FROM prompts WHERE type=? AND is_active=1',[$pt])){DB::q('UPDATE prompts SET is_active=(id=?) WHERE type=?',[$id,$pt]);}
    flash('Saved.');redirect(url('prompts',['t'=>$pt,'id'=>$id]));}
  if($a==='use'){$p=DB::row('SELECT type FROM prompts WHERE id=?',[$id]);if($p)DB::q('UPDATE prompts SET is_active=(id=?) WHERE type=?',[$id,$p['type']]);flash('Now in use.');redirect(url('prompts',['t'=>$p['type']??$t]));}
  if($a==='dup'){$p=DB::row('SELECT * FROM prompts WHERE id=?',[$id]);if($p){$n=DB::insert('prompts',['type'=>$p['type'],'name'=>$p['name'].' (copy)','subject'=>$p['subject'],'content'=>$p['content']]);redirect(url('prompts',['t'=>$p['type'],'id'=>$n]));}}
  if($a==='delete'){$p=DB::row('SELECT * FROM prompts WHERE id=?',[$id]);if($p&&$p['is_active'])flash('You cannot delete the prompt in use. Set another one in use first.','err');elseif($p){DB::q('DELETE FROM prompts WHERE id=?',[$id]);flash('Deleted.');}redirect(url('prompts',['t'=>$t]));}
  if($a==='reset'){foreach(Seed::prompts() as [$ty,$n,$s,$c])if($ty===$t){$nid=DB::insert('prompts',['type'=>$ty,'name'=>$n.' ('.date('d M').')','subject'=>$s,'content'=>$c,'is_default'=>1]);redirect(url('prompts',['t'=>$t,'id'=>$nid]));}}}
$list=DB::all('SELECT * FROM prompts WHERE type=? ORDER BY is_active DESC,updated_at DESC',[$t]);
$cur=isset($_GET['id'])?($_GET['id']==='new'?['id'=>0,'name'=>'','subject'=>'','content'=>'','is_active'=>0]:DB::row('SELECT * FROM prompts WHERE id=? AND type=?',[(int)$_GET['id'],$t])):($list[0]??null);
$isAI=strpos($t,'report_')===0;$isMail=strpos($t,'email')===0;
$vars=['business_name','category','city','address','phone','email','website','rating','reviews','keyword','report_link','agency_name','agency_phone','agency_email','agency_website','sender_name','currency','currency_symbol','yearly_fee','website_fee'];
if($isAI)$vars=array_merge($vars,['web_score','map_score','website_audit','map_audit','competitors','services']);
?>
<div class="tabs"><?php foreach($types as $k=>[$l]):?><a href="<?=url('prompts',['t'=>$k])?>" class="<?=$t===$k?'on':''?>"><?=e($l)?></a><?php endforeach?></div>
<div class="g3"><div class="col"><div class="card"><div class="card-h"><h3><?=e($types[$t][0])?></h3><a class="btn btn-sm btn-g" href="<?=url('prompts',['t'=>$t,'id'=>'new'])?>"><?=icon('plus')?>New</a></div><p class="hint"><?=e($types[$t][1])?></p><div class="plist"><?php foreach($list as $p):?><a href="<?=url('prompts',['t'=>$t,'id'=>$p['id']])?>" class="pi <?=$cur&&(int)$cur['id']===(int)$p['id']?'on':''?>"><b><?=e($p['name'])?></b><span><?=$p['is_active']?'<span class="bdg bdg-green">In use</span>':'<span class="bdg bdg-gray">Saved</span>'?><small><?=ago($p['updated_at'])?></small></span></a><?php endforeach?></div><form method="post" onsubmit="return confirm('Add a fresh copy of the default for this type?')"><?=csrf_field()?><input type="hidden" name="a" value="reset"><button class="btn btn-sm mt"><?=icon('refresh')?>Restore default as new</button></form></div>
<div class="card"><div class="card-h"><h3>Placeholders</h3></div><p class="hint">Click to copy. They are replaced for every lead.</p><div class="vars"><?php foreach($vars as $v):?><code onclick="A.copy('{{<?=$v?>}}')">{{<?=$v?>}}</code><?php endforeach?></div><?php if(!$isAI):?><p class="hint mt">Keep the first message simple – no fees. The PDF report is attached automatically.</p><?php else:?><p class="hint mt">The AI must return HTML. Scores, competitor table and detailed check tables are added to the PDF automatically, with your logo, colours and fonts from Settings.</p><?php endif?></div></div>
<div class="col col2"><?php if($cur):?><form method="post" class="card frm"><?=csrf_field()?><input type="hidden" name="a" value="save"><input type="hidden" name="id" value="<?=(int)$cur['id']?>"><input type="hidden" name="type" value="<?=e($t)?>"><div class="card-h"><h3><?=$cur['id']?'Edit':'New'?> <?=$isAI?'AI prompt':'message'?></h3><?php if($cur['id']):?><span><?=$cur['is_active']?'<span class="bdg bdg-green">In use</span>':'<span class="bdg bdg-gray">Saved</span>'?></span><?php endif?></div><label>Name<input name="name" value="<?=e($cur['name'])?>" required></label><?php if($isMail):?><label>Email subject<input name="subject" value="<?=e($cur['subject'])?>"></label><?php endif?><label><?=$isAI?'Prompt sent to the AI':'Message text'?><textarea name="content" rows="<?=$isAI?24:14?>" class="mono" required><?=e($cur['content'])?></textarea></label><label class="chk"><input type="checkbox" name="use" value="1" <?=$cur['is_active']?'checked':''?>> Use this <?=$isAI?'prompt':'message'?> (in use)</label><div class="row"><button class="btn btn-g"><?=icon('check')?>Save</button></div></form><?php if($cur['id']):?><div class="row mt"><?php if(!$cur['is_active']):?><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="use"><input type="hidden" name="id" value="<?=$cur['id']?>"><button class="btn"><?=icon('check')?>Set in use</button></form><?php endif?><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="dup"><input type="hidden" name="id" value="<?=$cur['id']?>"><button class="btn"><?=icon('copy')?>Duplicate</button></form><?php if(!$cur['is_active']):?><form method="post" onsubmit="return confirm('Delete this prompt?')"><?=csrf_field()?><input type="hidden" name="a" value="delete"><input type="hidden" name="id" value="<?=$cur['id']?>"><button class="btn red"><?=icon('trash')?>Delete</button></form><?php endif?></div><?php endif?><?php else:?><div class="card empty"><?=icon('msg')?><p>Select or create a prompt.</p></div><?php endif?></div></div>
